private const val MAX_EXPENSE_ATTACHMENT_BYTES=10L*1024L*1024L
private suspend fun readExpenseAttachment(context:android.content.Context,uri:Uri):Triple<String,String,ByteArray> = withContext(Dispatchers.IO){var name="attachment";var declared:Long?=null;context.contentResolver.query(uri,arrayOf(OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE),null,null,null)?.use{c->if(c.moveToFirst()){name=c.getString(0)?:name;declared=c.getLong(1).takeIf{it>=0}}};if(declared!=null&&declared!!>MAX_EXPENSE_ATTACHMENT_BYTES)throw IllegalArgumentException("Attachment is larger than 10 MB.");val input=context.contentResolver.openInputStream(uri)?:throw IllegalArgumentException("Attachment could not be opened.");val out=ByteArrayOutputStream(if(declared!=null)minOf(declared!!,MAX_EXPENSE_ATTACHMENT_BYTES).toInt()else 32*1024);input.use{stream->val buffer=ByteArray(32*1024);var total=0L;while(true){val count=stream.read(buffer);if(count<0)break;total+=count;if(total>MAX_EXPENSE_ATTACHMENT_BYTES)throw IllegalArgumentException("Attachment is larger than 10 MB.");out.write(buffer,0,count)};if(total==0L)throw IllegalArgumentException("Attachment is empty.")};Triple(name,context.contentResolver.getType(uri)?:"application/pdf",out.toByteArray())}
