@OptIn(ExperimentalLayoutApi::class) @Composable private fun ExpenseDetail(x:JsonObject,saving:Boolean,error:String?,onClose:()->Unit,onEdit:(JsonObject)->Unit,onAction:(String,String,String?,String?,String?)->Unit,onAttach:(String,String,String,ByteArray)->Unit,onDownload:(String,String)->Unit,onRecurring:(JsonObject)->Unit){
